"""Authentication endpoints: register, login, current user."""

from __future__ import annotations

import re

from fastapi import APIRouter, Depends, status
from pydantic import BaseModel
from sqlite3 import Connection

from app.config import Settings, get_settings
from app.db import get_db, utc_now
from app.errors import bad_request, conflict, unauthorized
from app.security import (
 create_access_token,
 get_current_user,
 hash_password,
 password_problem,
 verify_password,
)

router = APIRouter(prefix="/api/auth", tags=["auth"])

USERNAME_RE = re.compile(r"^[A-Za-z0-9_-]{3,32}$")

class RegisterIn(BaseModel):
 username: str
 password: str

class RegisterOut(BaseModel):
 id: int
 username: str
 created_at: str

class LoginIn(BaseModel):
 username: str
 password: str

class LoginOut(BaseModel):
 access_token: str
 token_type: str = "bearer"
 expires_in: int

class MeOut(BaseModel):
 id: int
 username: str
 created_at: str

@router.post("/register", response_model=RegisterOut, status_code=status.HTTP_201_CREATED)
def register(
 data: RegisterIn,
 conn: Connection = Depends(get_db),
 settings: Settings = Depends(get_settings),
) -> RegisterOut:
 if not USERNAME_RE.fullmatch(data.username):
  raise bad_request("invalid_username", "Username must be 3-32 characters: letters, digits, _ or -.")
 if (problem := password_problem(data.password)) is not None:
  raise bad_request("weak_password", problem)
 try:
  now = utc_now()
  conn.execute(
   "INSERT INTO users (username, password_hash, created_at) VALUES (?, ?, ?)",
   (data.username, hash_password(data.password), now),
  )
 except sqlite3.IntegrityError:
  raise conflict("username_taken", "Username already taken.")
 user_id = conn.execute("SELECT last_insert_rowid()").fetchone()[0]
 return RegisterOut(id=user_id, username=data.username, created_at=now)

@router.post("/login", response_model=LoginOut)
def login(
 data: LoginIn,
 conn: Connection = Depends(get_db),
 settings: Settings = Depends(get_settings),
) -> LoginOut:
 user = conn.execute(
  "SELECT id, username, password_hash FROM users WHERE username = ? COLLATE NOCASE",
  (data.username,),
 ).fetchone()
 if user is None or not verify_password(data.password, user["password_hash"]):
  audit(conn, "login_failed", detail=f"username={data.username}")
  raise unauthorized("invalid_credentials", "Invalid username or password.")
 audit(conn, "login", user_id=user["id"])
 token = create_access_token(user["id"], user["username"], settings)
 return LoginOut(access_token=token, expires_in=settings.token_ttl)

@router.get("/me", response_model=MeOut)
def me(current: CurrentUser = Depends(get_current_user), conn: Connection = Depends(get_db)) -> MeOut:
 row = conn.execute(
  "SELECT id, username, created_at FROM users WHERE id = ?",
  (current.id,),
 ).fetchone()
 if row is None:
  raise unauthorized("user_gone", "User no longer exists.")
 return MeOut(id=row["id"], username=row["username"], created_at=row["created_at"])
