from __future__ import annotations

from fastapi import APIRouter, Depends, Query, status
from pydantic import BaseModel, Field
from sqlite3 import Connection
from typing import Sequence

from app.config import Settings, get_settings
from app.db import get_db, utc_now, row_to_dict
from app.errors import not_found
from app.pagination import PageParams, page_params, paginate
from app.security import CurrentUser, get_current_user

router = APIRouter(prefix="/api/todos", tags=["todos"])

class TodoCreate(BaseModel):
 title: str = Field(min_length=1, max_length=200)

class TodoUpdate(BaseModel):
 title: str | None = Field(default=None, min_length=1, max_length=200)
 done: bool | None = None

class TodoOut(BaseModel):
 id: int
 title: str
 done: bool
 created_at: str
 updated_at: str

def _todo_row_to_out(row: sqlite3.Row) -> TodoOut:
 return TodoOut(
  id=row["id"],
  title=row["title"],
  done=bool(row["done"]),
  created_at=row["created_at"],
  updated_at=row["updated_at"],
 )

@router.get("", response_model=dict)
def list_todos(
 done: bool | None = Query(default=None),
 page: PageParams = Depends(page_params),
 current: CurrentUser = Depends(get_current_user),
 conn: Connection = Depends(get_db),
) -> dict:
 where = ["user_id = ?"]
 params: list[object] = [current.id]
 if done is not None:
  where.append("done = ?")
  params.append(1 if done else 0)
 where_sql = " AND ".join(where)
 total = conn.execute(f"SELECT COUNT(*) FROM todos WHERE {where_sql}", params).fetchone()[0]
 rows = conn.execute(
  f"SELECT id, title, done, created_at, updated_at FROM todos WHERE {where_sql} ORDER BY created_at DESC LIMIT ? OFFSET ?",
  (*params, page.limit, page.offset),
 ).fetchall()
 items = [_todo_row_to_out(row) for row in rows]
 return paginate(items, total, page)

@router.post("", response_model=TodoOut, status_code=status.HTTP_201_CREATED)
def create_todo(
 data: TodoCreate,
 current: CurrentUser = Depends(get_current_user),
 conn: Connection = Depends(get_db),
) -> TodoOut:
 now = utc_now()
 conn.execute(
  "INSERT INTO todos (user_id, title, done, created_at, updated_at) VALUES (?, ?, 0, ?, ?)",
  (current.id, data.title.strip(), now, now),
 )
 todo_id = conn.execute("SELECT last_insert_rowid()").fetchone()[0]
 row = conn.execute(
  "SELECT id, title, done, created_at, updated_at FROM todos WHERE id = ?",
  (todo_id,),
 ).fetchone()
 return _todo_row_to_out(row)

@router.get("/{todo_id}", response_model=TodoOut)
def get_todo(
 todo_id: int,
 current: CurrentUser = Depends(get_current_user),
 conn: Connection = Depends(get_db),
) -> TodoOut:
 row = conn.execute(
  "SELECT id, title, done, created_at, updated_at FROM todos WHERE id = ? AND user_id = ?",
  (todo_id, current.id),
 ).fetchone()
 if row is None:
  raise not_found("todo_not_found", "Todo not found.")
 return _todo_row_to_out(row)

@router.patch("/{todo_id}", response_model=TodoOut)
def update_todo(
 todo_id: int,
 data: TodoUpdate,
 current: CurrentUser = Depends(get_current_user),
 conn: Connection = Depends(get_db),
) -> TodoOut:
 row = conn.execute(
  "SELECT id, title, done, created_at, updated_at FROM todos WHERE id = ? AND user_id = ?",
  (todo_id, current.id),
 ).fetchone()
 if row is None:
  raise not_found("todo_not_found", "Todo not found.")
 updates = []
 params: list[object] = []
 if data.title is not None:
  updates.append("title = ?")
  params.append(data.title.strip())
 if data.done is not None:
  updates.append("done = ?")
  params.append(1 if data.done else 0)
 if not updates:
  return _todo_row_to_out(row)
 updates.append("updated_at = ?")
 params.append(utc_now())
 params.append(todo_id)
 conn.execute(f"UPDATE todos SET {', '.join(updates)} WHERE id = ?", params)
 row = conn.execute(
  "SELECT id, title, done, created_at, updated_at FROM todos WHERE id = ?",
  (todo_id,),
 ).fetchone()
 return _todo_row_to_out(row)

@router.delete("/{todo_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_todo(
 todo_id: int,
 current: CurrentUser = Depends(get_current_user),
 conn: Connection = Depends(get_db),
) -> None:
 cur = conn.execute(
  "DELETE FROM todos WHERE id = ? AND user_id = ?",
  (todo_id, current.id),
 )
 if cur.rowcount == 0:
  raise not_found("todo_not_found", "Todo not found.")
