import { apiFetch, ApiError, loadToken, clearToken, isSignedIn } from "./api.js";
import { showMessage, formValues, whileBusy, el, clear, formatTime } from "./ui.js";

const list = document.getElementById("list");
const addForm = document.getElementById("add-form");
const filterRadios = document.querySelectorAll('input[name="filter"]');
const prevBtn = document.getElementById("prev");
const nextBtn = document.getElementById("next");
const signoutBtn = document.getElementById("signout");
const usernameEl = document.getElementById("username");

let offset = 0;
let limit = 20;
let currentFilter = "all";
let total = 0;

if (!isSignedIn()) {
 location.href = "login.html";
}

async function loadUser() {
 try {
  const me = await apiFetch("/api/auth/me");
  usernameEl.textContent = me.username;
 } catch (err) {
  if (err instanceof ApiError && err.status === 401) {
   clearToken();
   location.href = "login.html";
  } else {
   showMessage("Failed to load user", "error");
  }
 }
}

async function loadTodos() {
 try {
  const query = new URLSearchParams({ limit: String(limit), offset: String(offset) });
  if (currentFilter !== "all") {
   query.set("done", currentFilter === "done" ? "true" : "false");
  }
  const res = await apiFetch(`/api/todos?${query.toString()}`);
  total = res.total;
  renderTodos(res.items);
  updatePager();
 } catch (err) {
  if (err instanceof ApiError) {
   showMessage(err.message, "error");
  } else {
   showMessage("Network error", "error");
  }
 }
}

function renderTodos(items) {
 clear(list);
 for (const todo of items) {
  const li = el("li", { class: "list-item" + (todo.done ? " done" : "") },
   el("input", { type: "checkbox", checked: todo.done, "data-id": todo.id, class: "toggle" }),
   el("span", { class: "title grow" }, todo.title),
   el("button", { class: "rename", "data-id": todo.id, "aria-label": "Rename" }, "✎"),
   el("button", { class: "danger delete", "data-id": todo.id, "aria-label": "Delete" }, "✕")
  );
  list.appendChild(li);
 }
}

function updatePager() {
 prevBtn.disabled = offset === 0;
 nextBtn.disabled = offset + limit >= total;
}

async function fetchWithAuth(path, options = {}) {
 return apiFetch(path, { ...options, auth: true });
}

list.addEventListener("click", async (e) => {
 const target = e.target;
 if (target.matches(".toggle")) {
  const id = Number(target.dataset.id);
  const done = target.checked;
  try {
   await fetchWithAuth(`/api/todos/${id}`, { method: "PATCH", body: { done } });
  } catch (err) {
   target.checked = !done;
   if (err instanceof ApiError) showMessage(err.message, "error");
   else showMessage("Network error", "error");
  }
 } else if (target.matches(".rename")) {
  const id = Number(target.dataset.id);
  const li = target.closest(".list-item");
  const titleEl = li.querySelector(".title");
  const currentTitle = titleEl.textContent;
  const newTitle = prompt("Rename todo:", currentTitle);
  if (newTitle === null || newTitle.trim() === "" || newTitle.trim() === currentTitle) return;
  try {
   await fetchWithAuth(`/api/todos/${id}`, { method: "PATCH", body: { title: newTitle.trim() } });
   titleEl.textContent = newTitle.trim();
  } catch (err) {
   if (err instanceof ApiError) showMessage(err.message, "error");
   else showMessage("Network error", "error");
  }
 } else if (target.matches(".delete")) {
  const id = Number(target.dataset.id);
  if (!confirm("Delete this todo?")) return;
  try {
   await fetchWithAuth(`/api/todos/${id}`, { method: "DELETE" });
   loadTodos();
  } catch (err) {
   if (err instanceof ApiError) showMessage(err.message, "error");
   else showMessage("Network error", "error");
  }
 }
});

addForm.addEventListener("submit", async (e) => {
 e.preventDefault();
 await whileBusy(addForm, async () => {
  const data = formValues(addForm);
  try {
   await fetchWithAuth("/api/todos", { method: "POST", body: data });
   addForm.reset();
   offset = 0;
   await loadTodos();
  } catch (err) {
   if (err instanceof ApiError) showMessage(err.message, "error");
   else showMessage("Network error", "error");
  }
 });
});

for (const radio of filterRadios) {
 radio.addEventListener("change", () => {
  currentFilter = radio.value;
  offset = 0;
  loadTodos();
 });
}

prevBtn.addEventListener("click", () => {
 offset = Math.max(0, offset - limit);
 loadTodos();
});

nextBtn.addEventListener("click", () => {
 offset += limit;
 loadTodos();
});

signoutBtn.addEventListener("click", () => {
 clearToken();
 location.href = "login.html";
});

loadUser();
loadTodos();
